public enum CMCStatusInfo_OtherInfoKind
{
    FailInfo,
    PendInfo,
}

public sealed class CMCStatusInfo_OtherInfo
{
    public CMCStatusInfo_OtherInfoKind Kind { get; private set; }
    public int? FailInfo { get; private set; }
    public PendInfo? PendInfo { get; private set; }

    public static CMCStatusInfo_OtherInfo FromFailInfo(int failInfo) => new CMCStatusInfo_OtherInfo
    {
        Kind = CMCStatusInfo_OtherInfoKind.FailInfo,
        FailInfo = failInfo,
    };

    public static CMCStatusInfo_OtherInfo FromPendInfo(PendInfo pendInfo) => new CMCStatusInfo_OtherInfo
    {
        Kind = CMCStatusInfo_OtherInfoKind.PendInfo,
        PendInfo = pendInfo,
    };

    public override string ToString()
    {
        return Kind switch
        {
            CMCStatusInfo_OtherInfoKind.FailInfo => Asn1Formatting.Format(FailInfo),
            CMCStatusInfo_OtherInfoKind.PendInfo => Asn1Formatting.Format(PendInfo),
            _ => "<unset>",
        };
    }

    public void Encode(Asn1Writer writer)
    {
        switch (Kind)
        {
            case CMCStatusInfo_OtherInfoKind.FailInfo:
                writer.WriteInteger(Asn1Tag.Integer, FailInfo.Value);
                break;
            case CMCStatusInfo_OtherInfoKind.PendInfo:
                PendInfo.Encode(writer, Asn1Tag.Sequence);
                break;
            default: throw new Asn1Exception("CHOICE has no alternative.");
        }
    }

    public static CMCStatusInfo_OtherInfo Decode(Asn1Reader reader)
    {
        if (!reader.TryPeekTag(out var peeked)) throw new Asn1Exception("Empty CHOICE.");
        var value = new CMCStatusInfo_OtherInfo();
        if (peeked.MatchesIgnoreConstructed(Asn1Tag.Integer))
        {
            value.Kind = CMCStatusInfo_OtherInfoKind.FailInfo;
            value.FailInfo = reader.ReadInt32(Asn1Tag.Integer);
        }
        else if (peeked.MatchesIgnoreConstructed(Asn1Tag.Sequence))
        {
            value.Kind = CMCStatusInfo_OtherInfoKind.PendInfo;
            value.PendInfo = Asn1Kit.Modern.EnrollmentMessageSyntax2009.PendInfo.Decode(reader, Asn1Tag.Sequence);
        }
        else throw new Asn1Exception("Unknown CHOICE alternative.");
        return value;
    }
}

